import Row from "react-bootstrap/Row";
import Col from "react-bootstrap/Col";
import { Link } from "react-router-dom";
import { Title, Container, HeaderContainer, HomePageButton } from "./styles";
import CancelIcon from "../../assets/images/cancel-icon.svg";
import {INVESTOR_URL_PREFIX} from "../../constants/routes";
import { useCompanyPrefix } from "../../utils/hooks";
import { getHomepageUrl } from "../../utils/routes";

const ScreenError = () => {
  const {companyPrefix} =useCompanyPrefix()

  const reloadHomePage = () => {
    setTimeout(() => {
      window.location.reload();
    }, 500);
  };

  return (
    <Container>
      <HeaderContainer>
        <Title>Something went wrong</Title>
      </HeaderContainer>
      <Row>
        <Col md={12} className="my-4">
          <img src={CancelIcon} alt="Cancel icon" />
          <span className="px-3">
            The sidecar team has been notified, please try again later.
          </span>
        </Col>
      </Row>
      <Row>
        <Col md={2} className="my-4 px-3">
          <Link to="#" onClick={()=>window.open(getHomepageUrl(companyPrefix),"_self")} style={{textDecoration: "none"}}>
            <HomePageButton
              onClick={reloadHomePage}
            >
              Go to homepage
            </HomePageButton>
          </Link>
        </Col>
      </Row>
    </Container>
  );
};

export default ScreenError;
